export const original='Academic writing often requires multiple rounds of revision. A clear review process helps authors inspect and improve their manuscripts.';
export const revised='Academic writing involves revising arguments, evidence, and expression across multiple drafts. Reviewing proposed changes alongside the rendered manuscript allows authors to understand each revision before deciding whether to adopt it.';
export const concise='Authors revise arguments, evidence, and expression across drafts. Reviewing each proposed change before adoption keeps the manuscript under the author’s control.';
export const fileList=['main.tex','sections/introduction.tex','references.bib','figures/workflow.svg','tables/overview.csv'];
export function newSession(title='论文起草与修改'){return {id:crypto.randomUUID(),title,messages:[],pending:[],draft:'',archived:false};}
export function seed(){const s=newSession();s.messages=[{role:'user',text:'请根据我们的提纲写出引言初稿，不新增实验结论。'},{role:'assistant',text:'已根据提纲整理初稿，保留了研究边界。正文、参考文献和素材会放在同一个项目中。',artifact:'初稿 · main.tex'},{role:'user',text:'这段更具体一些，保持克制。',quotes:[original]},{role:'assistant',text:'我会延续上面的写作要求，具体说明修改对象和审阅方式，不添加新的研究结论。',proposal:'p1'}];const archived=newSession('早期研究讨论');archived.archived=true;archived.messages=[{role:'user',text:'先讨论文章结构。'},{role:'assistant',text:'可以先整理研究问题、方法和证据，再开始写作。此处为归档会话示例。'}];return {active:'demo',projects:[{id:'demo',name:'Paper Studio',path:'~/Papers/paper-studio',accepted:original,files:[...fileList],sessions:[s,archived],session:s.id,proposals:[{id:'p1',text:revised,base:original,title:'引言修改',status:'pending',session:s.id,reason:'将笼统的“修改”细化为论证、证据与表达；说明作者如何审阅；保持原有研究边界。'}],history:[{title:'引言初稿',text:original,time:'今天 10:20',files:[...fileList]}]}]};}
